-- Textos nuevos de la web (zquare.uy) en Web → Contenido: los cinco
-- servicios (el quinto, Capacitaciones, es nuevo) y los cuatro pasos del
-- método, en español e inglés. Hasta ahora el contenido publicado era el
-- de la web original y pisaba a los textos nuevos de la página.
-- Los testimonios de ejemplo no se tocan.

update public.contenido_web set es = $j${"titulo": "Diagnóstico de procesos", "descripcion": "¿No sabés por dónde empezar con la IA?\n\nAnalizamos cómo trabaja tu empresa para identificar dónde la tecnología puede ahorrar tiempo, reducir costos y simplificar procesos.\nTe ayudamos a entender qué vale la pena mejorar, qué soluciones tienen sentido para tu negocio y por dónde conviene empezar.", "etiqueta": "Diagnóstico de procesos"}$j$, en = $j${"titulo": "Process diagnosis", "descripcion": "Don't know where to start with AI?\n\nWe analyze how your company works to identify where technology can save time, cut costs and simplify processes.\nWe help you understand what is worth improving, which solutions make sense for your business and where to start.", "etiqueta": "Process diagnosis"}$j$, publicado = true
  where tipo = 'servicio' and orden = 1 and deleted_at is null;
update public.contenido_web set es = $j${"titulo": "Asistentes y automatizaciones", "descripcion": "¿Tu equipo pierde tiempo en tareas repetitivas?\n\nDesarrollamos asistentes inteligentes y automatizaciones que se encargan de tareas que hoy requieren tiempo y trabajo manual.\nConectamos las herramientas que ya usás y automatizamos procesos para que tu equipo pueda enfocarse en lo que realmente importa.", "etiqueta": "Un asistente o automatización"}$j$, en = $j${"titulo": "Assistants & automations", "descripcion": "Does your team lose time on repetitive tasks?\n\nWe develop intelligent assistants and automations that take care of tasks that today require time and manual work.\nWe connect the tools you already use and automate processes so your team can focus on what really matters.", "etiqueta": "An assistant or automation"}$j$, publicado = true
  where tipo = 'servicio' and orden = 2 and deleted_at is null;
update public.contenido_web set es = $j${"titulo": "Sistemas a medida", "descripcion": "¿Te cuesta encontrar un sistema que se adapte a tu forma de trabajar?\n\nDiseñamos y desarrollamos sistemas a medida, pensados para las necesidades y los procesos de tu empresa.\nNos encargamos de todo el proceso: entendemos lo que necesitás, desarrollamos la solución y acompañamos a tu equipo para que pueda utilizarla.", "etiqueta": "Un sistema a medida"}$j$, en = $j${"titulo": "Custom systems", "descripcion": "Can't find a system that fits the way you work?\n\nWe design and build custom systems, made for the needs and processes of your company.\nWe take care of the whole process: we understand what you need, build the solution and support your team so they can use it.", "etiqueta": "A custom system"}$j$, publicado = true
  where tipo = 'servicio' and orden = 3 and deleted_at is null;
update public.contenido_web set es = $j${"titulo": "Datos e integraciones", "descripcion": "¿La información de tu empresa está repartida en distintos sistemas?\n\nConectamos las herramientas que ya usás para que tus datos estén organizados, actualizados y disponibles cuando los necesitás.\nEliminamos tareas duplicadas y transformamos la información de tu empresa en reportes claros que te ayudan a tomar mejores decisiones.", "etiqueta": "Datos e integraciones"}$j$, en = $j${"titulo": "Data & integrations", "descripcion": "Is your company information spread across different systems?\n\nWe connect the tools you already use so your data is organized, up to date and available when you need it.\nWe remove duplicate tasks and turn your company information into clear reports that help you make better decisions.", "etiqueta": "Data & integrations"}$j$, publicado = true
  where tipo = 'servicio' and orden = 4 and deleted_at is null;
update public.contenido_web set es = $j${"titulo": "Capacitaciones", "descripcion": "¿Querés que tu equipo incorpore la IA a su trabajo diario?\n\nCapacitamos a tu equipo para que aprenda a utilizar la inteligencia artificial de forma práctica, efectiva y responsable.\nAdaptamos cada capacitación a las tareas y necesidades reales de tu empresa, para que puedan aplicar lo aprendido desde el primer día. No se necesitan conocimientos previos.", "etiqueta": "Capacitaciones"}$j$, en = $j${"titulo": "Training", "descripcion": "Want your team to bring AI into their daily work?\n\nWe train your team to use artificial intelligence in a practical, effective and responsible way.\nWe adapt each training to the real tasks and needs of your company, so they can apply what they learn from day one. No prior knowledge needed.", "etiqueta": "Training"}$j$, publicado = true
  where tipo = 'servicio' and orden = 5 and deleted_at is null;
insert into public.contenido_web (tipo, orden, publicado, es, en)
  select 'servicio', 5, true, $j${"titulo": "Capacitaciones", "descripcion": "¿Querés que tu equipo incorpore la IA a su trabajo diario?\n\nCapacitamos a tu equipo para que aprenda a utilizar la inteligencia artificial de forma práctica, efectiva y responsable.\nAdaptamos cada capacitación a las tareas y necesidades reales de tu empresa, para que puedan aplicar lo aprendido desde el primer día. No se necesitan conocimientos previos.", "etiqueta": "Capacitaciones"}$j$, $j${"titulo": "Training", "descripcion": "Want your team to bring AI into their daily work?\n\nWe train your team to use artificial intelligence in a practical, effective and responsible way.\nWe adapt each training to the real tasks and needs of your company, so they can apply what they learn from day one. No prior knowledge needed.", "etiqueta": "Training"}$j$
  where not exists (select 1 from public.contenido_web where tipo = 'servicio' and orden = 5 and deleted_at is null);

update public.contenido_web set es = $j${"titulo": "Diagnóstico", "duracion": "1–2 semanas", "descripcion": "Charlamos con tu equipo y vemos cómo trabajan hoy. Al final te damos un plan: qué hacer primero, cuánto cuesta y cuánto demora."}$j$, en = $j${"titulo": "Discovery", "duracion": "1–2 weeks", "descripcion": "We talk with your team and see how you work today. At the end you get a plan: what to do first, what it costs and how long it takes."}$j$, publicado = true
  where tipo = 'paso' and orden = 1 and deleted_at is null;
update public.contenido_web set es = $j${"titulo": "Prueba", "duracion": "2–4 semanas", "descripcion": "Armamos una primera versión chica y la usan personas de tu empresa. Si no sirve, lo sabés antes de invertir más."}$j$, en = $j${"titulo": "Trial", "duracion": "2–4 weeks", "descripcion": "We build a small first version and people from your company use it. If it does not work, you know before investing more."}$j$, publicado = true
  where tipo = 'paso' and orden = 2 and deleted_at is null;
update public.contenido_web set es = $j${"titulo": "Construcción", "duracion": "Entregas cada 2 semanas", "descripcion": "Lo terminamos por partes y cada dos semanas te mostramos lo nuevo funcionando."}$j$, en = $j${"titulo": "Build", "duracion": "Releases every 2 weeks", "descripcion": "We finish it in parts, and every two weeks we show you what is new, working."}$j$, publicado = true
  where tipo = 'paso' and orden = 3 and deleted_at is null;
update public.contenido_web set es = $j${"titulo": "Acompañamiento", "duracion": "Mientras lo uses", "descripcion": "Arreglamos lo que falle y lo mejoramos con lo que te vaya pidiendo tu equipo."}$j$, en = $j${"titulo": "Support", "duracion": "For as long as you use it", "descripcion": "We fix whatever breaks and improve it with what your team asks for."}$j$, publicado = true
  where tipo = 'paso' and orden = 4 and deleted_at is null;
